using Health_Care_System.BLL.Interfaces; using Health_Care_System.Data; using Health_Care_System.Entities; using Microsoft.EntityFrameworkCore;
namespace Health_Care_System.BLL.Implementations;
public class AppointmentRepository: IAppointmentRepository { private readonly AppDbContext _context; public AppointmentRepository(AppDbContext context)=>_context=context; public async Task<IEnumerable<Appointment>> GetAllAsync()=>await _context.Appointments.Include(x=>x.Patient).Include(x=>x.Doctor).AsNoTracking().ToListAsync(); public async Task<Appointment?> GetAsync(int patientId,int doctorId)=>await _context.Appointments.Include(x=>x.Patient).Include(x=>x.Doctor).FirstOrDefaultAsync(x=>x.PatientId==patientId&&x.DoctorId==doctorId); public async Task CreateAsync(Appointment entity)=>await _context.Appointments.AddAsync(entity); public void Update(Appointment entity)=>_context.Appointments.Update(entity); public void Delete(Appointment entity)=>_context.Appointments.Remove(entity); }
